import SPRITE_MANIFEST from './SpriteManifest.json';

// Generated by `npm run assets` from public/assets/gifs
export type SpriteName = keyof typeof SPRITE_MANIFEST;

// Troop config / entity name → sprite sheet name prefix (from the source GIF filename)
export const CONFIG_TO_SPRITE: Record<string, string> = {
    'Archers': 'Archer',
    'Giant': 'Giant',
    'MiniPEKKA': 'MiniPekka',
    'Valkyrie': 'Valkyrie',
    'Wizard': 'Wizard',
    'BabyDragon': 'BabyDragon',
    'Barbarians': 'Barbarian',
    'InfernoTower': 'InfernoTower',
    'Cannon': 'Cannon',
    'Arrows': 'Arrows',
    'Fireball': 'FireBall',
    'Rage': 'Rage',
};

// GIF frames with a 0ms delay are shown briefly instead of skipped
const MIN_FRAME_MS = 50;

// Frames to drop from a sheet (artifacts in the source GIF)
const SKIP_FRAMES: Partial<Record<SpriteName, number[]>> = {
    BabyDragon_fight_player: [0], // first frame is a differently coloured dragon
};

// Sheet frame where the hit lands, when it isn't the last frame of the cycle
const IMPACT_FRAMES: Partial<Record<SpriteName, number>> = {
    FireBall_fight_player: 4, // explosion; later frames are lingering smoke
    FireBall_fight_opponent: 4,
};

export interface AnimTiming {
    frames: number[];    // sheet frame indices, in play order
    durations: number[]; // ms per frame
    total: number;       // ms for one cycle
    impactAt: number;    // ms into the cycle where the hit lands (default: start of the last frame)
}

export const spriteFor = (configName: string, action: 'walk' | 'fight', owner: 'player' | 'opponent') =>
    `${CONFIG_TO_SPRITE[configName] ?? configName}_${action}_${owner}` as SpriteName;

export const hasSprite = (name: string): name is SpriteName => name in SPRITE_MANIFEST;

/**
 * Length of one repeating cycle of a frame-delay pattern. Some GIFs loop several attacks
 * (e.g. Archers fires 5 volleys); uniform delays are treated as a single cycle.
 */
function cycleLength(delays: number[]): number {
    if (delays.every(d => d === delays[0])) return delays.length;
    for (let period = 2; period < delays.length; period++) {
        if (delays.length % period !== 0) continue;
        if (delays.every((d, i) => d === delays[i % period])) return period;
    }
    return delays.length;
}

/**
 * Timing for one cycle of a sprite. `fitTo` compresses the cycle to at most that many ms
 * (an attack animation must finish before the next attack starts); shorter cycles keep
 * their native GIF speed.
 */
export function getAnimTiming(sprite: SpriteName, options: { singleCycle?: boolean; fitTo?: number } = {}): AnimTiming {
    const { delays } = SPRITE_MANIFEST[sprite];
    const count = options.singleCycle ? cycleLength(delays) : delays.length;
    const skip = SKIP_FRAMES[sprite] ?? [];

    const frames: number[] = [];
    let durations: number[] = [];
    for (let i = 0; i < count; i++) {
        if (skip.includes(i)) continue;
        frames.push(i);
        durations.push(Math.max(MIN_FRAME_MS, delays[i]));
    }

    let total = durations.reduce((a, b) => a + b, 0);
    if (options.fitTo && total > options.fitTo) {
        const scale = options.fitTo / total;
        durations = durations.map(d => d * scale);
        total = options.fitTo;
    }

    const impactFrame = IMPACT_FRAMES[sprite];
    const impactIndex = impactFrame !== undefined ? frames.indexOf(impactFrame) : -1;
    const impactAt = impactIndex >= 0
        ? durations.slice(0, impactIndex).reduce((a, b) => a + b, 0)
        : total - durations[durations.length - 1];
    return { frames, durations, total, impactAt };
}

/** Attack animation timing for a troop: one attack cycle fitted inside its hit speed. */
export const getAttackTiming = (configName: string, owner: 'player' | 'opponent', hitSpeed: number): AnimTiming | null => {
    const sprite = spriteFor(configName, 'fight', owner);
    return hasSprite(sprite) ? getAnimTiming(sprite, { singleCycle: true, fitTo: hitSpeed }) : null;
};
